    internal async Task TapTry_on_value_task_receiver_with_sync_delegate_returns_the_error_of_the_handler_when_the_delegate_throws_the_named_exception_when_the_receiver_completes_later()
    {
        var error = Error.Create("Boom.");
        var handled = Error.Create("Handled.");
        var tapCalls = 0;
        var receiver = new ValueTask<Result<int>>(Pending.Of(Result.Success(2)));
        var outcome = await receiver.TapTry(x => { tapCalls++; Boom.Throw(); }, (InvalidOperationException _) => handled);

        Assert.Same(handled, outcome.GetError());
        Assert.Equal(1, tapCalls);
    }

